entries[6648] = { ["name"] = "Rolle des Totems der Steinhaut", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lehrt 'Totem der Steinhaut' (Rang 1).\nBeschwört ein Totem der Steinhaut mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem schützt Gruppen- und Schlachtzugsmitglieder in einem Umkreis von 40 Metern, erhöht die Rüstung um 4076 . Hält 5 Min. lang an." }
entries[6649] = { ["name"] = "Rolle des Totems der Verbrennung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lehrt 'Totem der Verbrennung' (Rang 1).\nBeschwört 1 Min. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das einen Feind im Umkreis von 20 Metern mehrfach angreift und ihm 96 Feuerschaden zufügt. Das Totem greift bevorzugt Gegner an, die von Euren Effekten 'Flammenschock' oder 'Sturmschlag' getroffen wurden." }
entries[6650] = { ["name"] = "Totem des heilenden Flusses Rolle", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lehrt 'Totem des heilenden Flusses' (Rang 1).\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem regeneriert 5 Min. lang alle 2 Sek. [( 28 + (Spell power * 0.0827) * (( 1 * 1 )))] Gesundheit aller Gruppenmitglieder in einem Umkreis von 30 Metern [ Glyphe 'Totem des heilenden Flusses' : und erhöht den Feuer-, Frost- und Naturwiderstand aller Gruppen- und Schlachtzugsmitglieder innerhalb von 30 Metern um [( 85 <= 70 ? 85 : ( 85 <= 80 ? 85 + ( 85 - 70) * 5 : 85 + ( 85 - 70) * 5 + ( 85 - 80) * 7))] ]." }
